CREATE TABLE IF NOT EXISTS apple_reminder_connections (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'ready', last_imported_at timestamp, last_error text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS apple_reminders (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, source text NOT NULL DEFAULT 'apple_reminders', external_id text NOT NULL, list_name text NOT NULL DEFAULT 'Reminders', title text NOT NULL, notes text, due_at timestamp, completed boolean NOT NULL DEFAULT false, last_synced_at timestamp NOT NULL DEFAULT now(), import_audit jsonb NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS apple_reminders_owner_external_uidx ON apple_reminders(user_id, external_id);
CREATE INDEX IF NOT EXISTS apple_reminders_user_idx ON apple_reminders(user_id);
CREATE TABLE IF NOT EXISTS planning_blocks (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, proposal_id text NOT NULL, source_type text NOT NULL, source_id text, title text NOT NULL, reason text NOT NULL, start_at timestamp NOT NULL, end_at timestamp NOT NULL, status text NOT NULL DEFAULT 'accepted', created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS planning_blocks_user_idx ON planning_blocks(user_id);
CREATE INDEX IF NOT EXISTS planning_blocks_proposal_idx ON planning_blocks(proposal_id);
CREATE TABLE IF NOT EXISTS life_memories (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, category text NOT NULL, source text NOT NULL, title text NOT NULL, summary text, source_date timestamp, related_area text, related_project_id text, confidence real NOT NULL DEFAULT 1, privacy_level text NOT NULL DEFAULT 'private', archived boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS life_memories_user_idx ON life_memories(user_id);
CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL, area text NOT NULL, status text NOT NULL DEFAULT 'active', priority text NOT NULL DEFAULT 'medium', progress integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), next_action text, deadline timestamp, notes text, milestones jsonb NOT NULL DEFAULT '[]', related_task_ids jsonb NOT NULL DEFAULT '[]', activity jsonb NOT NULL DEFAULT '[]', created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_user_idx ON projects(user_id);
